<?php
require __DIR__.'/../app/core.php';
if(!installed()){header('Location: setup.php');exit;}
$error=''; $notice='';
if($_SERVER['REQUEST_METHOD']==='POST') {
 try {
  csrf_check(); $act=$_POST['action']??'';
  if($act==='login') {
    if(is_rate_limited('login',10,900)) throw new RuntimeException('Too many login attempts');
    $admin=json_decode(file_get_contents(KITLAB_STORAGE.'/admin.json'),true);
    if(!hash_equals($admin['username'],(string)($_POST['username']??'')) || !password_verify((string)($_POST['password']??''),$admin['password_hash'])) throw new RuntimeException('Invalid credentials');
    session_regenerate_id(true); $_SESSION['admin']=true; $_SESSION['csrf']=bin2hex(random_bytes(24)); header('Location: admin.php');exit;
  }
  if($act==='logout') {unset($_SESSION['admin']);header('Location: admin.php');exit;}
  require_admin();
  if($act==='category') {
   $id=safe_text($_POST['id']??'',50); $name=safe_text($_POST['name']??'',80);$parent=safe_text($_POST['parent_id']??'',60);
   if(!$name) throw new RuntimeException('Category name required');
   $item=['id'=>$id?:uid(),'name'=>$name,'parent_id'=>($parent && $parent!==$id)?$parent:null,'sort'=>(int)($_POST['sort']??0),'active'=>true];
   update_data('categories',function (&$d) use($item,$id){$updated=false;foreach($d as &$r)if($r['id']===$id && $id!==''){$r=$item;$updated=true;break;} unset($r);if(!$updated)$d[]=$item;});
  } elseif($act==='product') {
   $id=safe_text($_POST['id']??'',60);$name=safe_text($_POST['name']??'',100);$cat=safe_text($_POST['category_id']??'',60);
   $shape=safe_text($_POST['shape']??'jersey',30);
   if(!$name || !in_array($cat,array_column(read_data('categories'),'id'),true))throw new RuntimeException('Valid name/category required');
   if(!in_array($shape,['jersey','rugby','singlet','hoodie','polo'],true))throw new RuntimeException('Unsupported garment shape');
   $item=['id'=>$id?:uid(),'category_id'=>$cat,'name'=>$name,'shape'=>$shape,'description'=>safe_text($_POST['description']??'',140),'active'=>true];
   update_data('products',function (&$d) use($item,$id){$updated=false;foreach($d as &$r)if($r['id']===$id && $id!==''){$r=$item;$updated=true;break;}unset($r);if(!$updated)$d[]=$item;});
  } elseif($act==='template') {
   $id=safe_text($_POST['id']??'',60);$name=safe_text($_POST['name']??'',100);$prod=safe_text($_POST['product_id']??'',60);
   $pattern=safe_text($_POST['pattern']??'solid',20);
   if(!$name || !in_array($prod,array_column(read_data('products'),'id'),true))throw new RuntimeException('Valid template and product required');
   if(!in_array($pattern,['solid','hoops','stripes','diagonal','chevron','flash'],true))throw new RuntimeException('Invalid pattern');
   $colors=[];for($i=1;$i<=4;$i++) {$color=$_POST['c'.$i]??'#ffffff';if(!valid_color($color))throw new RuntimeException('Invalid hex color');$colors[]=$color;}
   $item=['id'=>$id?:uid(),'product_id'=>$prod,'name'=>$name,'pattern'=>$pattern,'colors'=>$colors,'active'=>true];
   update_data('templates',function (&$d) use($item,$id){$updated=false;foreach($d as &$r)if($r['id']===$id && $id!==''){$r=$item;$updated=true;break;}unset($r);if(!$updated)$d[]=$item;});
  } elseif($act==='delete') {
   $collection=(string)($_POST['collection']??'');$id=safe_text($_POST['id']??'',60);
   if(!in_array($collection,['categories','products','templates'],true))throw new RuntimeException('Invalid collection');
   if($collection==='categories')foreach(read_data('categories') as $r)if(($r['parent_id']??null)===$id)throw new RuntimeException('Delete subcategories before their parent');
   if($collection==='categories')foreach(read_data('products') as $r)if($r['category_id']===$id)throw new RuntimeException('Category has products');
   if($collection==='products')foreach(read_data('templates') as $r)if($r['product_id']===$id)throw new RuntimeException('Delete linked templates first');
   update_data($collection,function (&$d)use($id){$d=array_values(array_filter($d,fn($r)=>$r['id']!==$id));});
  } elseif($act==='status') {
   $id=safe_text($_POST['id']??'',30);$status=safe_text($_POST['status']??'',30);
   if(!in_array($status,['New','Reviewing','Quoted','Approved','In Production','Dispatched','Closed'],true))throw new RuntimeException('Invalid status');
   update_data('orders',function (&$d)use($id,$status){foreach($d as &$r)if($r['id']===$id)$r['status']=$status;});
  } elseif($act==='settings') {
   $settings=['brand'=>safe_text($_POST['brand']??'',70),'contact_email'=>safe_text($_POST['contact_email']??'',120),'minimum_order'=>max(1,(int)($_POST['minimum_order']??1))];
   update_data('settings',function (&$d)use($settings){$d=$settings;});
  } elseif($act==='password') {
   $old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');
   $record=json_decode(file_get_contents(KITLAB_STORAGE.'/admin.json'),true);
   if(!password_verify($old,$record['password_hash']) || strlen($new)<12)throw new RuntimeException('Current password incorrect or new password shorter than 12 characters');
   $record['password_hash']=password_hash($new,PASSWORD_DEFAULT);file_put_contents(KITLAB_STORAGE.'/admin.json',json_encode($record),LOCK_EX);
  }
  header('Location: admin.php?ok=1');exit;
 } catch(Throwable $e){$error=$e->getMessage();}
}
if(!is_admin()):
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KitLab Admin Login</title><link rel="stylesheet" href="assets/styles.css"><body class="auth-page"><main class="auth-card"><div class="brand"><span class="brand-mark">W</span><div>WINSUN <b>KITLAB</b><small>ADMINISTRATION</small></div></div><h1>Welcome back</h1><p>Sign in to manage your live designer.</p><?php if($error):?><div class="alert"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="login"><label>Username<input name="username" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary full">Sign in</button></form><a class="subtle-link" href="index.php">← Back to studio</a></main></body></html>
<?php exit;endif;
$categories=read_data('categories');$products=read_data('products');$templates=read_data('templates');$orders=array_reverse(read_data('orders'));
$settings=array_merge(['brand'=>'Winsun Sportswear','contact_email'=>'sales@winsunsportswear.com','minimum_order'=>15],read_data('settings'));
$tab=in_array($_GET['tab']??'',['catalog','orders','settings'],true)?$_GET['tab']:'catalog';
function opt($values,$selected=null,$empty=false):void {if($empty)echo '<option value="">Top-level category</option>';foreach($values as $r)echo '<option value="'.h($r['id']).'" '.($selected===$r['id']?'selected':'').'>'.h($r['name']).'</option>';}
function hidden($act):void {echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><input type="hidden" name="action" value="'.h($act).'">';}
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KitLab Admin</title><link rel="stylesheet" href="assets/styles.css"><link rel="stylesheet" href="assets/admin.css"><body class="admin-page"><aside class="admin-side"><a class="brand" href="index.php"><span class="brand-mark">W</span><div>WINSUN <b>KITLAB</b><small>ADMIN CONSOLE</small></div></a><nav><a href="admin.php?tab=catalog" class="<?=$tab==='catalog'?'active':''?>">▦ &nbsp; Catalog manager</a><a href="admin.php?tab=orders" class="<?=$tab==='orders'?'active':''?>">▤ &nbsp; Orders <small><?=count($orders)?></small></a><a href="admin.php?tab=settings" class="<?=$tab==='settings'?'active':''?>">⚙ &nbsp; Settings</a><a href="index.php" target="_blank">↗ &nbsp; Open designer</a></nav><form method="post"><?php hidden('logout');?><button class="logout">Sign out →</button></form></aside><main class="admin-main"><div class="admin-top"><div><p class="eyebrow">WORKSPACE / MANAGEMENT</p><h1><?=$tab==='catalog'?'Product catalog':($tab==='orders'?'Customer orders':'Studio settings')?></h1></div><span class="admin-pill">● &nbsp; System active</span></div><?php if($error):?><div class="alert"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="success">Changes saved successfully.</div><?php endif;?>
<?php if($tab==='catalog'):?><section class="metrics"><div><small>SPORTS & GROUPS</small><strong><?=count($categories)?></strong></div><div><small>LIVE PRODUCTS</small><strong><?=count($products)?></strong></div><div><small>DESIGN TEMPLATES</small><strong><?=count($templates)?></strong></div><div><small>ORDERS</small><strong><?=count($orders)?></strong></div></section>
<div class="admin-two"><section class="admin-panel"><h2>Categories & subcategories</h2><p>Use a parent category to build nested navigation.</p><form method="post" class="admin-form"><?php hidden('category');?><input name="name" placeholder="Category name" required><select name="parent_id"><?php opt($categories,null,true);?></select><button class="btn primary">Add category</button></form><div class="admin-rows"><?php foreach($categories as $row):?><details><summary><?=h($row['name'])?><span><?=h($row['parent_id']?:'Top level')?> · edit</span></summary><form method="post" class="inline-edit"><?php hidden('category');?><input type="hidden" name="id" value="<?=h($row['id'])?>"><input name="name" value="<?=h($row['name'])?>"><select name="parent_id"><?php opt($categories,$row['parent_id'],true);?></select><button class="btn small">Update</button></form><form method="post" onsubmit="return confirm('Delete category?')"><?php hidden('delete');?><input type="hidden" name="id" value="<?=h($row['id'])?>"><input type="hidden" name="collection" value="categories"><button class="text-danger">Delete category</button></form></details><?php endforeach;?></div></section>
<section class="admin-panel"><h2>Product models</h2><p>Add garments and choose their live vector silhouette.</p><form method="post" class="admin-form"><?php hidden('product');?><input name="name" placeholder="Product name" required><select name="category_id" required><?php opt($categories);?></select><select name="shape"><option value="jersey">Soccer / T-shirt</option><option value="rugby">Rugby</option><option value="singlet">Singlet</option><option value="hoodie">Hoodie</option><option value="polo">Polo</option></select><input name="description" placeholder="Short description"><button class="btn primary">Add product</button></form><div class="admin-rows"><?php foreach($products as $row):?><details><summary><?=h($row['name'])?><span><?=h($row['shape'])?> · edit</span></summary><form method="post" class="inline-edit"><?php hidden('product');?><input type="hidden" name="id" value="<?=h($row['id'])?>"><input name="name" value="<?=h($row['name'])?>"><select name="category_id"><?php opt($categories,$row['category_id']);?></select><select name="shape"><?php foreach(['jersey','rugby','singlet','hoodie','polo'] as $s)echo '<option '.($s===$row['shape']?'selected':'').' value="'.h($s).'">'.h($s).'</option>';?></select><input name="description" value="<?=h($row['description']??'')?>"><button class="btn small">Update</button></form><form method="post" onsubmit="return confirm('Delete product?')"><?php hidden('delete');?><input type="hidden" name="id" value="<?=h($row['id'])?>"><input type="hidden" name="collection" value="products"><button class="text-danger">Delete product</button></form></details><?php endforeach;?></div></section></div>
<section class="admin-panel"><div class="panel-heading"><div><h2>Design templates</h2><p>Every template below appears instantly in the matching product designer.</p></div></div><form method="post" class="template-form"><?php hidden('template');?><label>Template name<input name="name" required placeholder="E.g. Pulse 02"></label><label>Product<select name="product_id"><?php opt($products);?></select></label><label>Pattern<select name="pattern"><?php foreach(['solid','hoops','stripes','diagonal','chevron','flash'] as $pattern)echo '<option value="'.h($pattern).'">'.ucfirst($pattern).'</option>';?></select></label><?php foreach([1,2,3,4] as $i):?><label>Colour <?=$i?><input type="color" name="c<?=$i?>" value="<?=['#142b54','#eeeeee','#d8ff48','#ffffff'][$i-1]?>"></label><?php endforeach;?><button class="btn primary">Create template</button></form><div class="template-admin-grid"><?php foreach($templates as $row):?><details class="template-entry"><summary><i style="background:linear-gradient(125deg,<?=h($row['colors'][0])?> 0 45%,<?=h($row['colors'][1])?> 45% 75%,<?=h($row['colors'][2])?> 75%)"></i><b><?=h($row['name'])?></b><small><?=h($row['product_id'])?></small></summary><form method="post" class="inline-edit"><?php hidden('template');?><input type="hidden" name="id" value="<?=h($row['id'])?>"><input name="name" value="<?=h($row['name'])?>"><select name="product_id"><?php opt($products,$row['product_id']);?></select><select name="pattern"><?php foreach(['solid','hoops','stripes','diagonal','chevron','flash'] as $pattern)echo '<option '.($pattern===$row['pattern']?'selected':'').' value="'.h($pattern).'">'.ucfirst($pattern).'</option>';?></select><?php foreach([1,2,3,4] as $i):?><label>Colour <?=$i?><input type="color" name="c<?=$i?>" value="<?=h($row['colors'][$i-1]??'#ffffff')?>"></label><?php endforeach;?><button class="btn small">Save template</button></form><form method="post" onsubmit="return confirm('Remove template?')"><?php hidden('delete');?><input type="hidden" name="id" value="<?=h($row['id'])?>"><input type="hidden" name="collection" value="templates"><button class="text-danger">Delete</button></form></details><?php endforeach;?></div></section>
<?php elseif($tab==='orders'):?><section class="admin-panel"><h2>All customer orders</h2><?php if(!$orders):?><p>No orders submitted yet.</p><?php endif;?><div class="orders-list"><?php foreach($orders as $o):?><details><summary><b>#<?=h($o['id'])?></b> &nbsp; <?=h($o['name'])?> <small><?=h($o['status'])?> · <?=h($o['created_at'])?></small></summary><div class="order-content"><p><b>Email:</b> <a href="mailto:<?=h($o['email'])?>"><?=h($o['email'])?></a> &nbsp; <b>Phone:</b> <?=h($o['phone'])?> &nbsp; <b>Team:</b> <?=h($o['club'])?></p><p><b>Product:</b> <?=h($o['product_id'])?> &nbsp; <b>Design:</b> <a target="_blank" href="index.php?design=<?=h($o['design_id'])?>">Open submitted design ↗</a></p><p><b>Notes:</b> <?=h($o['notes'])?></p><p><b>Roster:</b> <?=h(json_encode($o['roster']))?></p><p><b>Sizes:</b> <?=h(json_encode($o['sizes']))?></p><form method="post" class="inline-edit"><?php hidden('status');?><input type="hidden" name="id" value="<?=h($o['id'])?>"><select name="status"><?php foreach(['New','Reviewing','Quoted','Approved','In Production','Dispatched','Closed'] as $st)echo '<option '.($st===$o['status']?'selected':'').' value="'.h($st).'">'.h($st).'</option>';?></select><button class="btn primary small">Update order</button></form></div></details><?php endforeach;?></div></section>
<?php else:?><div class="admin-two"><section class="admin-panel"><h2>Business settings</h2><form method="post" class="admin-form"><?php hidden('settings');?><label>Brand name<input name="brand" value="<?=h($settings['brand'])?>"></label><label>Contact email<input type="email" name="contact_email" value="<?=h($settings['contact_email'])?>"></label><label>Minimum order quantity<input type="number" min="1" name="minimum_order" value="<?=h($settings['minimum_order'])?>"></label><button class="btn primary">Save settings</button></form></section><section class="admin-panel"><h2>Account security</h2><form method="post" class="admin-form"><?php hidden('password');?><label>Current password<input type="password" name="old_password" required></label><label>New password (12+ characters)<input type="password" name="new_password" required minlength="12"></label><button class="btn">Change password</button></form></section></div><?php endif;?></main></body></html>
